# owner: platform
import unittest

from rosterkit.seating import seating_rows
from rosterkit.models import Student


# ---
def make_student(last, first):
    ident = f"{last}-{first}"
    return Student(ident, last, first, "A")


class SeatingTests(unittest.TestCase):
    def setUp(self):
        self.pupils = [
            make_student("Halloway", "Juno"),
            make_student("Zane", "Ola"),
            make_student("Dunmere", "Piet")
        ]

    def test_sorted_and_chunked(self):
        self.assertEqual(
            seating_rows(self.pupils, 2),
            [
                "Row 1: Dunmere, Piet | Halloway, Juno",
                "Row 2: Zane, Ola"
            ]
        )

    def test_single_row(self):
        rows = seating_rows(self.pupils, 10)
        self.assertEqual(len(rows), 1)

    def test_ties_break_on_first_name(self):
        pair = [
            make_student("Reyes", "Zoe"),
            make_student("Reyes", "Ana")
        ]
        self.assertEqual(
            seating_rows(pair, 2),
            ["Row 1: Reyes, Ana | Reyes, Zoe"]
        )

    def test_bad_seat_count(self):
        for seats in (0, -3):
            with self.assertRaises(ValueError):
                seating_rows(self.pupils, seats)

    def test_no_students(self):
        with self.assertRaises(ValueError):
            seating_rows([], 3)


if __name__ == "__main__":
    unittest.main()
